\newcommand{\Q}{\mathbb{Q}}
\newcommand{\R}{\mathbb{R}}
\newcommand{\EML}{\mathrm{EML}}
\newcommand{\EL}{\mathrm{EL}}
\title{Transcendence and Multiplication Elimination in Rational\\Exponential--Logarithmic Expression Classes}
\author{Aristotle}
\date{July 26, 2026}

\begin{document}
\maketitle

\begin{abstract}
We study two classes of real numbers generated from rational constants by finite expression trees. The rational EML language permits a distinguished variable, exponentiation, logarithms, addition, and multiplication; the rational EL sublanguage omits multiplication. Closed values are obtained by setting the variable to zero. We prove unconditionally that every EL number is an EML number and that $\exp(\exp(1))+\log 2$ is represented by a rational EML expression. We isolate a functional strengthening of Schanuel's conjecture with three explicit assumptions: classical real Schanuel, algebraic independence over $\Q$ of $\exp(\exp(1))$ and $\log 2$, and extensional elimination of multiplication from rational EML expressions. A substitution theorem shows that the sum of two algebraically independent reals is transcendental. It follows conditionally that the displayed constant is transcendental. The elimination assumption gives the reverse class inclusion and hence $\EML=\EL$. We keep classical Schanuel logically separate from the two additional predictions and discuss algorithms, applications, and generalizations.
\end{abstract}

\section{Introduction}
Expressions formed from rational constants, exponentials, logarithms, sums, and products are easy to evaluate numerically and difficult to classify arithmetically. The constant
\[
\alpha=\exp(\exp(1))+\log 2
\]
illustrates the gap. Its decimal expansion can be computed rapidly, but no decimal computation determines whether it is algebraic over $\Q$.

A second question concerns expressive power. If a language already contains exponentiation, logarithms, and addition, does explicit multiplication enlarge its represented number class? The identity $ab=\exp(\log a+\log b)$ suggests otherwise for positive inputs, but signs, zeros, and real logarithms prevent it from furnishing a uniform translation for arbitrary nested expressions.

We define two precise grammars and state an explicit conjectural package. Its clauses are modular: the concrete transcendence result uses a pair-independence clause, while equality of number classes uses a functional multiplication-elimination clause. Neither additional clause is claimed to follow here from classical Schanuel.

\section{Algebraic preliminaries}
\begin{definition}
For fields $K\subseteq L$, an element $u\in L$ is \emph{algebraic over $K$} if $p(u)=0$ for some nonzero $p\in K[T]$. Otherwise $u$ is \emph{transcendental over $K$}.
\end{definition}

\begin{definition}
Elements $u_1,\ldots,u_n\in L$ are \emph{algebraically independent over $K$} if $P(u_1,\ldots,u_n)=0$ for $P\in K[X_1,\ldots,X_n]$ implies $P=0$. The transcendence degree $\operatorname{trdeg}_K L$ is the cardinality of a transcendence basis of $L/K$.
\end{definition}

Algebraic independence is stronger than separate transcendence. If $u$ is transcendental, then $u$ and $1-u$ are separately transcendental but satisfy $X+Y-1=0$.

\begin{conjecture}[Classical real Schanuel]
If $z_1,\ldots,z_n\in\R$ are linearly independent over $\Q$, then
\[
\operatorname{trdeg}_{\Q}\Q(z_1,\ldots,z_n,e^{z_1},\ldots,e^{z_n})\ge n.
\]
\end{conjecture}

\section{The expression classes}
Fix a distinguished real variable $t$.

\begin{definition}[Rational EML expression]
A rational EML expression is generated recursively as follows: every $q\in\Q$ and the variable $t$ are expressions; if $E$ is an expression, then $\exp(E)$ and $\log(E)$ are expressions; if $E,F$ are expressions, then $E+F$ and $EF$ are expressions.
\end{definition}

Each expression defines a function $\llbracket E\rrbracket:\R\to\R$ by recursive evaluation:
\[
\llbracket q\rrbracket(x)=q,\quad \llbracket t\rrbracket(x)=x,
\]
\[
\llbracket\exp(E)\rrbracket(x)=\exp(\llbracket E\rrbracket(x)),\quad
\llbracket\log(E)\rrbracket(x)=\log(\llbracket E\rrbracket(x)),
\]
with addition and multiplication interpreted pointwise. The standard total real-function convention for $\log$ is used consistently in both languages.

\begin{definition}[EML number]
A real number $a$ is a rational EML number if $\llbracket E\rrbracket(0)=a$ for some rational EML expression $E$. The set of all such values is denoted $\EML$.
\end{definition}

\begin{definition}[Rational EL expression and EL number]
A rational EL expression is generated by the same rules but without the multiplication constructor. A real number $a$ is an EL number if $\llbracket F\rrbracket(0)=a$ for such an expression $F$. The resulting class is denoted $\EL$.
\end{definition}

\begin{proposition}[Language inclusion]
Every rational EL expression is a rational EML expression.
\end{proposition}
\begin{proof}
Use structural induction. Constants and the variable occur in both grammars, and the exponential, logarithm, and addition constructors are shared. There is no multiplication case in the EL grammar.
\end{proof}

\begin{corollary}[Unconditional class inclusion]
$\EL\subseteq\EML$.
\end{corollary}
\begin{proof}
An EL expression representing $a$ at zero is, by the proposition, an EML expression with the same evaluation.
\end{proof}

\begin{proposition}[Representation of the concrete constant]
The expression
\[
E_\alpha(t)=\exp(\exp(1))+\log 2
\]
is a rational EML expression and satisfies
\[
\llbracket E_\alpha\rrbracket(0)=\exp(\exp(1))+\log 2.
\]
Thus $\alpha\in\EML$.
\end{proposition}
\begin{proof}
Start with rational constants $1$ and $2$, apply exponentiation twice to the first and logarithm once to the second, then add. Recursive evaluation gives the formula.
\end{proof}

In fact this displayed expression has no multiplication node and is also EL. Its role is not to separate the classes, but to connect the grammar with a concrete transcendence question.

\section{A functional strengthening of Schanuel}
\begin{hypothesis}[Functional EML strengthening]
Assume the following three clauses.
\begin{enumerate}[label=(\roman*)]
\item Classical real Schanuel's conjecture holds.
\item The numbers $\exp(\exp(1))$ and $\log 2$ are algebraically independent over $\Q$.
\item For every rational EML expression $E$, there exists a rational EL expression $F$ such that
\[
\llbracket F\rrbracket(x)=\llbracket E\rrbracket(x)
\qquad\text{for all }x\in\R.
\]
\end{enumerate}
\end{hypothesis}

Clauses (ii) and (iii) are additional predictions, not consequences of clause (i) established in this paper. Clause (iii) is extensional: it preserves the whole function rather than only its value at zero. It is consequently stronger than equality of the closed-value classes.

\section{Independent pairs have transcendental sums}
\begin{theorem}[Sum theorem]
If $x,y\in\R$ are algebraically independent over $\Q$, then $x+y$ is transcendental over $\Q$.
\end{theorem}
\begin{proof}
Suppose $x+y$ were algebraic. Choose nonzero $p(T)\in\Q[T]$ with $p(x+y)=0$, and set
\[
Q(X,Y)=p(X+Y)\in\Q[X,Y].
\]
Then $Q(x,y)=0$, so algebraic independence forces $Q=0$. But specializing $Y=0$ gives $Q(X,0)=p(X)$. Hence $Q=0$ would imply $p=0$, a contradiction. Therefore no nonzero rational polynomial vanishes at $x+y$.
\end{proof}

Equivalently, substitution $p(T)\mapsto p(X+Y)$ is injective because specialization at $Y=0$ is a left inverse. Separate transcendence would not suffice; joint independence rules out coordinated cancellation.

\begin{corollary}[Conditional transcendence]
Under the functional EML strengthening,
\[
\exp(\exp(1))+\log 2
\]
is transcendental over $\Q$.
\end{corollary}
\begin{proof}
Clause (ii) gives algebraic independence of $x=\exp(\exp(1))$ and $y=\log 2$. Apply the sum theorem.
\end{proof}

This statement is conditional. No unconditional conclusion about this constant's transcendence is claimed.

\section{Multiplication elimination}
\begin{theorem}[Reverse inclusion under elimination]
Under clause (iii) of the functional EML strengthening, $\EML\subseteq\EL$.
\end{theorem}
\begin{proof}
Let $a\in\EML$. Choose a rational EML expression $E$ with $\llbracket E\rrbracket(0)=a$. Clause (iii) supplies a rational EL expression $F$ agreeing with $E$ for every real input. At zero,
\[
\llbracket F\rrbracket(0)=\llbracket E\rrbracket(0)=a,
\]
so $a\in\EL$.
\end{proof}

\begin{theorem}[Conditional class equality]
Under the functional EML strengthening,
\[
\EML=\EL.
\]
\end{theorem}
\begin{proof}
The reverse-inclusion theorem gives $\EML\subseteq\EL$, and the unconditional class inclusion gives $\EL\subseteq\EML$.
\end{proof}

This is equality of represented values. The elimination premise is stronger: it is a semantics-preserving translation of complete expression functions.

\section{Algorithms and numerical demonstrations}
\subsection{Recursive evaluation}
Store an expression as a rooted tree. Constants and variables are leaves; exponential and logarithm nodes have one child; addition and multiplication nodes have two. Recursively evaluate children and apply the node operation. A tree with $N$ nodes is evaluated in $O(N)$ operations and $O(h)$ stack space, where $h$ is its height.

For the featured expression, ordinary floating-point arithmetic gives
\[
e^e\approx15.154262241479264,
\quad \log 2\approx0.6931471805599453,
\]
\[
\alpha\approx15.84740942203921.
\]
These values demonstrate evaluation, not transcendence.

\subsection{Bounded relation searches}
Given an approximation $a$, degree bound $d$, and coefficient bound $B$, enumerate all nonzero vectors $(c_0,\ldots,c_d)\in\{-B,\ldots,B\}^{d+1}$ and rank
\[
\left|\sum_{k=0}^d c_ka^k\right|.
\]
Horner evaluation costs $O(d)$ per vector, for total time $O(d(2B+1)^{d+1})$ and $O(d)$ auxiliary space. A failed finite search does not prove transcendence, and a small floating-point residual does not prove algebraicity.

For a pair $(x,y)$, enumerate bounded coefficients of monomials $X^iY^j$ with $i+j\le d$. There are $(d+1)(d+2)/2$ monomials, so exhaustive search is exponential in that count. It illustrates low-complexity relations but cannot establish algebraic independence.

\subsection{Polynomial substitution}
For $p(T)=\sum_{k=0}^d a_kT^k$, construct
\[
Q(X,Y)=\sum_{k=0}^d\sum_{j=0}^k
 a_k\binom{k}{j}X^jY^{k-j}.
\]
The dense output has $O(d^2)$ coefficients and takes $O(d^2)$ rational operations to produce. Specializing $Y=0$ recovers $p(X)$, which is the computational content of the sum theorem's injectivity argument.

\section{Applications and interpretation}
The sum theorem is a reusable template. More generally, if $x_1,\ldots,x_n$ are algebraically independent and rational coefficients $c_i$ are not all zero, then a substitution argument should show that $\sum_i c_ix_i$ is transcendental. The theorem above is the two-variable coefficient vector $(1,1)$.

The EML/EL comparison is also an instance of conservative extension. The richer grammar has an extra primitive. Extensional elimination acts as a compiler from rich trees to restricted trees, with equality on every input as its correctness specification. Evaluating at zero turns functional correctness into equality of number classes.

Three tasks should remain distinct: recognition of whether a tree lies in a grammar, recursive evaluation of its denoted function, and elimination of multiplication. The first two are algorithmic from the definitions. The third is conjectural mathematical content.

Numerical evidence has strict limits. Both algebraic and transcendental numbers can be approximated arbitrarily closely by numbers of the other kind. Nested exponentials also amplify conditioning problems. Computational experiments must therefore report precision and search bounds and should never be interpreted as proofs of algebraicity or transcendence.

\section{Discussion and future work}
The dependency structure is modular. Grammar alone yields $\EL\subseteq\EML$ and represents the concrete constant. Pure algebra proves the sum theorem. Concrete pair independence yields conditional transcendence. Functional elimination yields the reverse inclusion and class equality. Classical Schanuel supplies the intended setting but is not used to conceal either additional assumption.

Five problems arise naturally.
\begin{enumerate}
\item Determine whether classical Schanuel implies algebraic independence of $\exp(\exp(1))$ and $\log 2$, or whether the latter is genuinely stronger.
\item Formulate an exponential-algebraic closedness principle that, together with Schanuel, implies extensional multiplication elimination.
\item Establish separate transcendence of $\exp(\exp(1))$ and $\log 2$ under classical Schanuel, then investigate joint independence.
\item Extend both grammars to finitely many variables and compare their represented-function classes.
\item Prove transcendence of every nonzero rational linear combination of a finite algebraically independent family.
\end{enumerate}

\section{Conclusion}
A compact expression grammar organizes a broad family of exponential--logarithmic constants. The inclusion $\EL\subseteq\EML$ and representation of $\exp(\exp(1))+\log 2$ are unconditional structural facts. Algebraic independence of two reals forces transcendence of their sum through the injective substitution $p(T)\mapsto p(X+Y)$. Under the explicit pair-independence clause, the featured constant is therefore transcendental. Under the separate multiplication-elimination clause, the two number languages represent exactly the same reals. The assumptions identify precise targets rather than masking the conjectural frontier.

\end{document}

