class Const: value: Decimal
@dataclass(frozen=True)
class Var: pass
@dataclass(frozen=True)
class Unary: op: str; child: "Expr"
@dataclass(frozen=True)
class Binary: op: str; left: "Expr"; right: "Expr"
Expr = Union[Const, Var, Unary, Binary]
def evaluate(e: Expr, x: Decimal) -> Decimal:
    if isinstance(e, Const): return e.value
    if isinstance(e, Var): return x
    if isinstance(e, Unary):
        v = evaluate(e.child, x)
        return v.exp() if e.op == "exp" else v.ln()
    a, b = evaluate(e.left, x), evaluate(e.right, x)
    return a+b if e.op == "add" else a*b

from decimal import Decimal
from itertools import product
from typing import List, Tuple
def horner(c: Tuple[int, ...], x: Decimal) -> Decimal:
    r = Decimal(0)
    for a in reversed(c): r = r*x + a
    return r
def search(x: Decimal, d: int, b: int, keep: int=10) -> List[Tuple[Decimal, Tuple[int,...]]]:
    out=[]
    for c in product(range(-b,b+1), repeat=d+1):
        if any(c): out.append((abs(horner(c,x)), c))
    return sorted(out)[:keep]

from math import comb
from typing import Dict, Sequence, Tuple
def expand_p_of_x_plus_y(c: Sequence[int]) -> Dict[Tuple[int,int], int]:
    out: Dict[Tuple[int,int], int] = {}
    for k, a in enumerate(c):
        for j in range(k+1):
            out[j,k-j] = out.get((j,k-j),0) + a*comb(k,j)
    return {m:a for m,a in out.items() if a}

